const uor01Text = $('Extract UOR-01 Text').first().json.data || '';
const uor03Text = $('Extract UOR-03 Text').first().json.data || '';

function parseLines(text) {
  const out = [];
  let failures = 0;
  text.split('\n').filter((l) => l.trim().length > 0).forEach((line) => {
    try { out.push(JSON.parse(line)); } catch (e) { failures++; }
  });
  return { records: out, failures };
}

const uor01 = parseLines(uor01Text);
const uor03 = parseLines(uor03Text);
const countsMatch = uor01.records.length === uor03.records.length;

const DIMENSIONS_SCORED_BY_UOR01 = [
  'demand_signal_strength', 'revenue_potential', 'competition_level',
  'fulfillment_difficulty', 'automation_potential', 'recurring_revenue_potential',
  'scalability', 'compatibility_with_existing_stack', 'speed_to_first_revenue',
  'customer_acquisition_difficulty'
];

const DIMENSIONS_NOT_YET_COMPUTABLE = [
  'market_saturation', 'ease_of_market_entry', 'fulfillment_time',
  'startup_cost', 'marginal_fulfillment_cost', 'required_new_skills',
  'required_new_tools', 'defensibility', 'platform_risk', 'longevity',
  'commercial_intent'
];

const groups = new Map();
uor01.records.forEach((rec, idx) => {
  const key = rec.opportunity_id ?? `__no_id_${idx}`;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push({ rec, idx });
});

const outputRows = [];
const seenIds = new Set();

uor01.records.forEach((rec, idx) => {
  const id = rec.opportunity_id ?? `__no_id_${idx}`;
  if (seenIds.has(id)) return;
  seenIds.add(id);

  const group = groups.get(id);
  const scores = group
    .map((g) => (typeof g.rec.final_score === 'number' ? g.rec.final_score : null))
    .filter((s) => s !== null);

  const observation_count = group.length;
  let reconciled_opportunity_score = null;
  let score_variance = null;
  let score_reconciliation_status;

  if (scores.length === 0) {
    score_reconciliation_status = 'NO_SCORABLE_OBSERVATIONS';
  } else if (observation_count === 1) {
    reconciled_opportunity_score = scores[0];
    score_variance = 0;
    score_reconciliation_status = 'SINGLE_OBSERVATION';
  } else {
    reconciled_opportunity_score = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    score_variance = Math.max(...scores) - Math.min(...scores);
    score_reconciliation_status = 'RECONCILED_MULTI_OBSERVATION';
  }

  let evidence_confidence_v2_latest = null;
  if (countsMatch) {
    const evidenceValues = group
      .map((g) => uor03.records[g.idx])
      .filter(Boolean)
      .map((e) => e.evidence_confidence_v2)
      .filter((v) => typeof v === 'number');
    if (evidenceValues.length) {
      evidence_confidence_v2_latest = evidenceValues[evidenceValues.length - 1];
    }
  }

  outputRows.push({
    opportunity_id: rec.opportunity_id ?? null,
    observation_count,
    component_scores: scores,
    reconciled_opportunity_score,
    score_variance,
    score_reconciliation_status,
    evidence_confidence_v2_latest,
    dimensions_scored_by_uor01: DIMENSIONS_SCORED_BY_UOR01,
    dimensions_not_yet_computable: Object.fromEntries(
      DIMENSIONS_NOT_YET_COMPUTABLE.map((d) => [d, null])
    ),
    scoring_formula_version: 'uor04-v1-reconciliation-2026-09-05',
    computed_at: new Date().toISOString(),
  });
});

const fileText = outputRows.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    uor01_record_count: uor01.records.length,
    uor01_parse_failures: uor01.failures,
    uor03_record_count: uor03.records.length,
    uor03_parse_failures: uor03.failures,
    uor03_alignment_warning: countsMatch ? null : `UOR-01 and UOR-03 record counts differ (${uor01.records.length} vs ${uor03.records.length}) -- UOR-03 enrichment may be stale; evidence_confidence values omitted this run`,
    unique_opportunity_count: outputRows.length,
    file_text: fileText,
  },
}];
